INSERT INTO GTM_DEMO.APP.DEMO_ACCOUNTS (ACCOUNT_KEY, ACCOUNT_NAME, REGION, DEMO_STORY) VALUES
('GTM-0001', 'Northstar Field Services', 'NA', 'Hero account. Expansion opp + Oct 14 call on consolidating scheduling tools. Composer is tempted to claim ''expanding into three new regions'' (not in evidence) -> validator retry.'),
('GTM-0002', 'Juniper Ridge Health', 'EMEA', 'New logo, rising intent. Critical-events feature UNKNOWN. Trap claim: ''Series C funding round''.'),
('GTM-0003', 'Cobalt Ledger Systems', 'NA', 'Upgrade. Stale evidence (scored 6 days ago), PTB/ROP UNSCORED, no calls in 90 days, seats at 92%. Incomplete contact data. Trap claim: ''replacing your ERP next quarter''.'),
('GTM-0004', 'Harborline Logistics', 'NA', 'Renewal at risk. Escalated integration case, falling usage, competitor RouteSphere on the last call.'),
('GTM-0005', 'Verdant Grid Energy', 'EMEA', 'Failure mode: strong intent but every contact has opted out -> ''no permitted contact'', no draft.'),
('GTM-0006', 'Tessellate Retail Group', 'APAC', 'Mid-priority new logo from a webinar; competitor TaskNimbus mentioned.'),
('GTM-0007', 'Quarry & Pine Manufacturing', 'NA', 'UNSCORED account: shows ''not scored'' rather than ''low priority''.'),
('GTM-0008', 'Lumen Arc Media', 'NA', 'Closed-lost in April on budget; budget reopened on an Oct 20 call -> re-engagement.'),
('GTM-0009', 'Brightwater Insurance', 'NA', 'Clean expansion: proposal stage, 4 of 4 buying roles covered. The ''everything goes right'' run.'),
('GTM-0010', 'Kestrel Biotech', 'EMEA', 'Low priority; no budget until 2027. Bottom of the queue.');
