INSERT INTO GTM_DEMO.RAW_GONG.TRANSCRIPT_UTTERANCES (CALL_ID, UTTERANCE_NUM, START_SEC, SPEAKER, TEXT) VALUES
('GONG-8650', '1', '0', 'Alex Rivera (Acme)', 'Thanks for making time. I wanted to walk through adoption since the platform went live.'),
('GONG-8650', '2', '64', 'Riley Chen', 'Adoption is solid in the central region. Crews use it daily for job assignment.'),
('GONG-8650', '3', '125', 'Jordan Patel', 'I joined in August to run business systems, so I''m still mapping what we have.'),
('GONG-8650', '4', '186', 'Jordan Patel', 'We have a lot of overlapping tools. That''s one of the things I''ve been asked to clean up.'),
('GONG-8650', '5', '250', 'Alex Rivera (Acme)', 'Which tools overlap the most today?'),
('GONG-8650', '6', '296', 'Riley Chen', 'Scheduling. Each region picked its own tool before we standardized dispatch.'),
('GONG-8650', '7', '356', 'Jordan Patel', 'Let''s pick that up next month once I have the inventory done.'),
('GONG-8812', '1', '0', 'Alex Rivera (Acme)', 'Last time you mentioned scheduling tools differ by region. Where did the inventory land?'),
('GONG-8812', '2', '64', 'Riley Chen', 'We''re running three different scheduling tools across our field regions. It''s a mess for dispatch.'),
('GONG-8812', '3', '131', 'Riley Chen', 'The goal is to consolidate scheduling onto one platform and keep dispatch data in one place.'),
('GONG-8812', '4', '196', 'Riley Chen', 'The big question is integration. Our dispatch system has to stay the source for job status.'),
('GONG-8812', '5', '261', 'Alex Rivera (Acme)', 'That''s the pattern we see with other service operators. The integration is usually the long pole.'),
('GONG-8812', '6', '328', 'Riley Chen', 'Jordan wants a decision before Q1 planning closes.'),
('GONG-8812', '7', '379', 'Riley Chen', 'We don''t have anyone technical on our side assigned yet, honestly.'),
('GONG-8812', '8', '436', 'Alex Rivera (Acme)', 'I''ll send a short outline of how others sequenced it.'),
('GONG-8977', '1', '0', 'Alex Rivera (Acme)', 'Thanks for responding to the webinar follow-up. What prompted the interest?'),
('GONG-8977', '2', '60', 'Amara Okafor', 'We''re rolling out a new EHR across our clinics and clinical ops workflows are still on spreadsheets.'),
('GONG-8977', '3', '128', 'Amara Okafor', 'I''d want our IT director involved before we go further.'),
('GONG-9034', '1', '0', 'Alex Rivera (Acme)', 'Can you walk me through the EHR rollout plan?'),
('GONG-9034', '2', '50', 'Amara Okafor', 'Clinics go live in waves. Integration timelines with the EHR vendor keep slipping.'),
('GONG-9034', '3', '112', 'Lukas Brandt', 'Anything new needs to pass our security review and data residency checks in the EU.'),
('GONG-9034', '4', '174', 'Lukas Brandt', 'We looked at FlowBridge last year but it couldn''t handle the EHR events.'),
('GONG-9034', '5', '233', 'Amara Okafor', 'Sequencing is the real problem: which clinic workflows move first.'),
('GONG-9034', '6', '290', 'Amara Okafor', 'Our CFO would need to sign off on anything over budget, I''d have to check with her.'),
('GONG-9034', '7', '352', 'Alex Rivera (Acme)', 'I''ll share how other health-tech teams sequenced rollout around their EHR go-live.'),
('GONG-7120', '1', '0', 'Alex Rivera (Acme)', 'You''re fully onboarded. Anything blocking the finance team?'),
('GONG-7120', '2', '54', 'Sam Okoro', 'No, close workflows are running well. We''ll reach out if we need more seats.'),
('GONG-8890', '1', '0', 'Nina Alvarez', 'The TMS sync is failing several times a week. Dispatch is re-keying shipment status by hand.'),
('GONG-8890', '2', '65', 'Grace Kim', 'My team has stopped trusting the dashboard. They check the TMS directly now.'),
('GONG-8890', '3', '125', 'Alex Rivera (Acme)', 'That''s on us. Engineering has a fix in testing and I''ll get you a date.'),
('GONG-9101', '1', '0', 'Alex Rivera (Acme)', 'I wanted to start the renewal conversation and hear how things are going.'),
('GONG-9101', '2', '59', 'Marcus Bell', 'Honestly, the sync failures have hurt. My team has lost confidence.'),
('GONG-9101', '3', '116', 'Marcus Bell', 'We''re also taking a look at RouteSphere. They pitched a native TMS connector.'),
('GONG-9101', '4', '176', 'Owen Price', 'Procurement will need a stronger price if we renew with the issues we''ve had.'),
('GONG-9101', '5', '236', 'Marcus Bell', 'Fix the sync and show me it''s stable for a month, then we can talk.'),
('GONG-8740', '1', '0', 'Pieter Smit', 'We schedule grid maintenance crews across the region and it''s all manual today.'),
('GONG-8740', '2', '61', 'Pieter Smit', 'We''ll be publishing an RFP for crew scheduling software. Please don''t contact the team directly until then.'),
('GONG-9050', '1', '0', 'Arjun Mehta', 'We roll out tasks to about 400 stores and have no idea what actually gets done.'),
('GONG-9050', '2', '61', 'Arjun Mehta', 'We trialed TaskNimbus but store managers found it too heavy.'),
('GONG-9050', '3', '116', 'Arjun Mehta', 'A 20-store pilot would be the way in. Our head of store ops owns the budget.'),
('GONG-8601', '1', '0', 'Greg Novak', 'Plant 2 comes online in the spring. We''d like to clone our plant 1 workflows.'),
('GONG-8601', '2', '60', 'Greg Novak', 'Linda will want to see plant 1 results before approving more licenses.'),
('GONG-9120', '1', '0', 'Jasmine Reed', 'Good timing. Budget for content tooling reopened in our FY27 plan.'),
('GONG-9120', '2', '57', 'Jasmine Reed', 'Price was the sticking point last time, so we''d want a smaller starting scope.'),
('GONG-9120', '3', '118', 'Alex Rivera (Acme)', 'That''s easy to do. I''ll come back with a phased option.'),
('GONG-8833', '1', '0', 'David Park', 'Claims intake has to integrate with our policy admin system through the existing API gateway.'),
('GONG-8833', '2', '66', 'Kevin Liu', 'The new claims team is 120 people. SSO group mapping has to work on day one.'),
('GONG-9077', '1', '0', 'Rachel Stone', 'The expansion makes sense. Claims cycle time is the metric I''m measured on.'),
('GONG-9077', '2', '60', 'Monica Hayes', 'I need the ROI model before this goes to procurement.'),
('GONG-9077', '3', '112', 'Monica Hayes', 'Security questionnaire has to be back before November 15.'),
('GONG-9077', '4', '166', 'Alex Rivera (Acme)', 'I''ll send the ROI model this week and get the questionnaire to our security team today.'),
('GONG-8920', '1', '0', 'Isabelle Roux', 'We''re interested but there''s no budget for new tools until 2027.');
